// pageURL tries multiple URLs for a given page path.
func pageURL(path string) string {
	base := "http://127.0.0.1:8080"
	if os.Getenv("WEB_HOST") != "" {
		base = "http://" + os.Getenv("WEB_HOST") + ":8080"
	}
	return base + path
}

// fetchPage gets HTML content from a URL. Skips if unreachable.
func fetchPage(t *testing.T, path string) string {
	t.Helper()
	urls := []string{
		fmt.Sprintf("http://127.0.0.1:8080%s", path),
		fmt.Sprintf("http://localhost:8080%s", path),
	}
	var lastErr error
	for _, u := range urls {
		client := &http.Client{Timeout: 5 * time.Second}
		resp, err := client.Get(u)
		if err != nil {
			lastErr = err
			continue
		}
		defer resp.Body.Close()
		if resp.StatusCode != 200 {
			lastErr = fmt.Errorf("HTTP %d", resp.StatusCode)
			continue
		}
		data, err := io.ReadAll(resp.Body)
		if err != nil {
			lastErr = err
			continue
		}
		return string(data)
	}
	t.Skipf("page %s not reachable: %v", path, lastErr)
	return ""
}

// TestPageHasRealBalanceData checks that the trading page HTML contains
// assetsData with non-zero totalUSD and chain-specific balances.
func TestPageHasRealBalanceData(t *testing.T) {
	html := fetchPage(t, "/trading")
	if html == "" {
		return
	}

	// 1. Extract assetsData JS variable
	re := regexp.MustCompile(`var assetsData = (.+?);`)
	m := re.FindStringSubmatch(html)
	if len(m) < 2 {
		t.Fatal("FATAL: assetsData NOT FOUND in page HTML — balance card won't render anything")
	}

	var assets []map[string]interface{}
	if err := json.Unmarshal([]byte(m[1]), &assets); err != nil {
		t.Fatalf("FATAL: cannot parse assetsData JSON: %v", err)
	}
	t.Logf("assetsData: %d tokens", len(assets))

	if len(assets) == 0 {
		t.Fatal("FATAL: assetsData is empty array — no tokens in balance card")
	}

	// 2. Check chain distribution
	chains := map[string]struct{ all, pos int; total float64 }{}
	for _, a := range assets {
		ch, _ := a["chain_name"].(string)
		if ch == "" {
			t.Errorf("BUG: asset has empty chain_name: %v", a["ticker"])
			continue
		}
		c := chains[ch]
		c.all++
		amt, _ := a["amount"].(float64)
		usd, _ := a["usd_value"].(float64)
		c.total += usd
		if amt > 0.000001 {
			c.pos++
		}
		chains[ch] = c
	}

	for ch, c := range chains {
		t.Logf("  %s: %d tokens, %d positive, $%.4f", ch, c.all, c.pos, c.total)
		// Don't fail on zero — allowed with empty key
		if c.all == 0 {
			t.Errorf("BUG: chain %s has 0 tokens", ch)
		}
	}

	// 3. Check totalUSD JS variable
	reTotal := regexp.MustCompile(`var totalUSD = (.+?);`)
	mTotal := reTotal.FindStringSubmatch(html)
	if len(mTotal) < 2 {
		t.Error("FATAL: totalUSD variable not found in page")
	} else {
		var total float64
		fmt.Sscanf(mTotal[1], "%f", &total)
		t.Logf("totalUSD in page: $%.6f", total)
	}
}

// TestChainPanelVisible checks that the chain-panel has the 'open' class
// and is NOT hidden by CSS display:none alone.
func TestChainPanelVisible(t *testing.T) {
	html := fetchPage(t, "/portfolio")

	// The CSS says: .chain-panel{display:none} .chain-panel.open{display:block}
	// The HTML should have class="chain-panel" (starts closed, user toggles open).
	// Verify that the CSS toggle mechanism exists so the panel CAN become visible.
	hasCSSDisplayNone := strings.Contains(html, ".chain-panel{display:none")
	hasCSSOpenBlock := strings.Contains(html, ".chain-panel.open{display:block")
	hasChainPanelDiv := strings.Contains(html, `class="chain-panel"`)
	hasToggleJS := strings.Contains(html, "toggleChainPanel")

	t.Logf("CSS display:none found: %v", hasCSSDisplayNone)
	t.Logf("CSS .open display:block found: %v", hasCSSOpenBlock)
	t.Logf("HTML chain-panel div found: %v", hasChainPanelDiv)
	t.Logf("toggleChainPanel JS found: %v", hasToggleJS)

	if !hasChainPanelDiv {
		t.Error("BUG: chain-panel div not found in HTML")
	}
	if hasCSSDisplayNone && !hasCSSOpenBlock {
		t.Error("BUG: .chain-panel{display:none} exists but no .chain-panel.open{display:block}")
	}
}

// TestPageHasUnlockWalletJS checks the unlock JS function exists.
func TestPageHasUnlockWalletJS(t *testing.T) {
	html := fetchPage(t, "/trading")
	if html == "" {
		return
	}

	hasUnlock := strings.Contains(html, "function unlockWallet")
	hasPkInput := strings.Contains(html, `id="pkInput"`)
	hasRefresh := strings.Contains(html, "refreshAssetPanel")

	t.Logf("unlockWallet function: %v", hasUnlock)
	t.Logf("pkInput element: %v", hasPkInput)
	t.Logf("refreshAssetPanel call: %v", hasRefresh)

	if !hasUnlock {
		t.Error("BUG: unlockWallet JS function missing — can't unlock wallet from web")
	}
	if !hasPkInput {
		t.Error("BUG: pkInput element missing — no private key input field")
	}
}

// TestSchoolPageDBBrowser checks the School page has the DB browser
// with populateDBTables and loadDBTable functions.
func TestSchoolPageDBBrowser(t *testing.T) {
	html := fetchPage(t, "/school")
	if html == "" {
		return
	}

	hasPop := strings.Contains(html, "function populateDBTables")
	hasLoad := strings.Contains(html, "function loadDBTable")
	hasSelect := strings.Contains(html, `id="dbTableSelect"`)
	hasFetch := strings.Contains(html, "/api/database_tables")

	t.Logf("populateDBTables function: %v", hasPop)
	t.Logf("loadDBTable function: %v", hasLoad)
	t.Logf("dbTableSelect element: %v", hasSelect)
	t.Logf("fetch /api/database_tables: %v", hasFetch)

	if !hasPop && html != "" {
		t.Error("BUG: populateDBTables NOT in page — DB dropdown won't populate")
	}
	if !hasSelect && html != "" {
		t.Error("BUG: dbTableSelect NOT in page — no DB table selector")
	}
	if !hasFetch {
		t.Error("BUG: /api/database_tables endpoint not referenced — can't fetch tables")
	}
}

// TestFullUnlockBalanceFlow does the full unlock → balance flow end-to-end.
// 1. Write a fake key to unlock (won't work, just tests the flow)
// 2. Poll balance until it updates
func TestFullUnlockBalanceFlow(t *testing.T) {
	html := fetchPage(t, "/trading")
	if html == "" {
		return
	}

	// 1. Check initial assetsData has real total (from config.env key)
	re := regexp.MustCompile(`var totalUSD = (.+?);`)
	m := re.FindStringSubmatch(html)
	if len(m) < 2 {
		t.Fatal("totalUSD not in page")
	}
	var initialTotal float64
	fmt.Sscanf(m[1], "%f", &initialTotal)
	t.Logf("Initial totalUSD: $%.6f", initialTotal)

	// 2. Verify totalUSD is non-zero when key is set in config.env
	pk := os.Getenv("PRIVATE_KEY")
	if pk == "" {
		// Try from file
		data, _ := os.ReadFile("config.env")
		for _, line := range strings.Split(string(data), "\n") {
			line = strings.TrimSpace(line)
			if strings.HasPrefix(line, "PRIVATE_KEY=") {
				pk = strings.SplitN(line, "=", 2)[1]
			}
		}
	}
	if pk == "" {
		t.Skip("no PRIVATE_KEY — cannot validate balance")
	}

	// 3. The page should ALREADY have real data since key is in config.env
	// and governance regenerates every 10s. Check if initial total makes sense.
	if initialTotal < 0.01 && pk != "" {
		t.Errorf("BUG: totalUSD=$%.6f but private key IS set — balance should be non-zero. Check if governance is running and has generated the dashboard.", initialTotal)
	}

	// 4. Verify chain breakdown exists in page
	reAssets := regexp.MustCompile(`var assetsData = (.+?);`)
	mAssets := reAssets.FindStringSubmatch(html)
	if len(mAssets) < 2 {
		t.Fatal("assetsData not in page")
	}
	var assets []map[string]interface{}
	json.Unmarshal([]byte(mAssets[1]), &assets)

	chainPositive := map[string]int{}
	for _, a := range assets {
		ch, _ := a["chain_name"].(string)
		amt, _ := a["amount"].(float64)
		if amt > 0.000001 {
			chainPositive[ch]++
		}
	}
	t.Logf("Chains with positive balance: %v", chainPositive)

	// With a real key, expect at least BSC to have positive tokens
	if initialTotal > 0 && len(chainPositive) == 0 {
		t.Error("BUG: totalUSD>0 but no tokens have positive amounts — data mismatch")
	}
}

// TestPageNoMockData verifies the page does NOT contain hardcoded mock data.
func TestPageNoMockData(t *testing.T) {
	html := fetchPage(t, "/trading")
	if html == "" {
		return
	}

	mockStrings := []string{"LSTM_v2", "RandomForest_v3", "BTT", "CAKE", "SHIB"}
	found := []string{}
	for _, s := range mockStrings {
		if strings.Contains(html, s) {
			found = append(found, s)
		}
	}
	if len(found) > 0 {
		t.Logf("Note: strings found in page (may be real data or legacy): %v", found)
		// BTT, SHIB etc may be REAL balances, not mock
	} else {
		t.Log("No mock strings found — page uses real data")
	}

	// Check that TotalUSD is actually embedded as a number, not a placeholder
	hasZeroPlaceholder := strings.Contains(html, `totalUSD = 0;`) || strings.Contains(html, `totalUSD = 0.0;`)
	if hasZeroPlaceholder {
		t.Log("WARNING: totalUSD is 0 in page — may be no-key scenario or fresh startup")
	}
}
